def transform(grid):
    # Extend the colored vertical markers through the otherwise blank area above/below
    # the horizontal separator, matching the complete pattern in both panels.
    h, w = len(grid), len(grid[0])
    sep = next((r for r,row in enumerate(grid) if row and len(set(row)) == 1 and row[0] != 0), None)
    if sep is None:
        return [row[:] for row in grid]
    colors = {}
    for c in range(w):
        vals = {grid[r][c] for r in range(h) if r != sep and grid[r][c] != 0}
        if len(vals) == 1:
            colors[c] = next(iter(vals))
    out = [row[:] for row in grid]
    for r in range(h):
        if r != sep:
            for c,v in colors.items():
                out[r][c] = v
    return out
